    private static readonly Dictionary<SoftwareSectionId, Geometry> Cache = new();

    public static Geometry? Geometry(SoftwareSectionId section)
    {
        if (Cache.TryGetValue(section, out var cached)) return cached;
        var data = PathData(section);
        if (data.Length == 0) return null;
        try
        {
            var geometry = System.Windows.Media.Geometry.Parse(data);
            geometry.Freeze();
            Cache[section] = geometry;
            return geometry;
        }
        catch
        {
            return null;
        }
    }

    public static Path? Icon(SoftwareSectionId section, Brush fill, double size = 14)
    {
        var geometry = Geometry(section);
        return geometry is null ? null : new Path
        {
            Data = geometry,
            Fill = fill,
            Stretch = Stretch.Uniform,
            Width = size,
            Height = size,
            SnapsToDevicePixels = true
        };
    }
}
